pub(super) const LEGACY_NOT_COOPERABLE_STATUS_VALUE: &str = "X不合作";

pub(super) const ANCHOR_LEVEL_SORT_ASC_SQL: &str = "CASE WHEN NULLIF(BTRIM(COALESCE(anchor_level, '')), '') IS NULL THEN 99 WHEN anchor_level ~ '超头' THEN 1 WHEN anchor_level ~ '(中腰|腰部)' THEN 4 WHEN anchor_level ~ '肩部' THEN 3 WHEN anchor_level ~ '尾部' THEN 5 WHEN anchor_level ~ '头部' THEN 2 WHEN UPPER(BTRIM(anchor_level)) = 'S' OR UPPER(BTRIM(anchor_level)) LIKE 'S-%' THEN 1 WHEN UPPER(BTRIM(anchor_level)) = 'A' OR UPPER(BTRIM(anchor_level)) LIKE 'A-%' THEN 2 WHEN UPPER(BTRIM(anchor_level)) = 'B' OR UPPER(BTRIM(anchor_level)) LIKE 'B-%' THEN 3 WHEN UPPER(BTRIM(anchor_level)) = 'C' OR UPPER(BTRIM(anchor_level)) LIKE 'C-%' THEN 4 WHEN UPPER(BTRIM(anchor_level)) = 'D' OR UPPER(BTRIM(anchor_level)) LIKE 'D-%' THEN 5 ELSE 98 END ASC, id DESC";

pub(super) const ANCHOR_LEVEL_SORT_DESC_SQL: &str = "CASE WHEN NULLIF(BTRIM(COALESCE(anchor_level, '')), '') IS NULL THEN 99 WHEN anchor_level ~ '超头' THEN 1 WHEN anchor_level ~ '(中腰|腰部)' THEN 4 WHEN anchor_level ~ '肩部' THEN 3 WHEN anchor_level ~ '尾部' THEN 5 WHEN anchor_level ~ '头部' THEN 2 WHEN UPPER(BTRIM(anchor_level)) = 'S' OR UPPER(BTRIM(anchor_level)) LIKE 'S-%' THEN 1 WHEN UPPER(BTRIM(anchor_level)) = 'A' OR UPPER(BTRIM(anchor_level)) LIKE 'A-%' THEN 2 WHEN UPPER(BTRIM(anchor_level)) = 'B' OR UPPER(BTRIM(anchor_level)) LIKE 'B-%' THEN 3 WHEN UPPER(BTRIM(anchor_level)) = 'C' OR UPPER(BTRIM(anchor_level)) LIKE 'C-%' THEN 4 WHEN UPPER(BTRIM(anchor_level)) = 'D' OR UPPER(BTRIM(anchor_level)) LIKE 'D-%' THEN 5 ELSE 98 END DESC, id DESC";
